import { test, expect } from '@playwright/test';

test.describe('API Data Loading Skeleton', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/data-fetch');
  });

  test('should display loading skeleton while API data is fetching', async ({ page }) => {
    // Verify loading skeleton is visible
    const skeleton = page.getByTestId('loading-skeleton');
    await expect(skeleton).toBeVisible();

    // Verify API request is initiated
    const requestPromise = page.waitForResponse('**/api/data');
    await requestPromise;

    // Verify loading skeleton disappears and data is displayed
    const dataContainer = page.getByTestId('data-container');
    await expect(dataContainer).not.toBeVisible();

    const dataList = page.getByTestId('data-list');
    await expect(dataList).toBeVisible();

    // Verify data is displayed
    const dataItem = page.getByText('Item 1');
    await expect(dataItem).toBeVisible();

    // Verify API response contains data
    const responseBody = await requestPromise.json();
    expect(responseBody).toHaveProperty('items');
    expect(responseBody.items).toHaveLength(3);
  });

  test('should handle API error and display error message', async ({ page }) => {
    // Mock API error response
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Verify loading skeleton is visible
    const skeleton = page.getByTestId('loading-skeleton');
    await expect(skeleton).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText('Failed to load data');
    await expect(errorMessage).toBeVisible();

    // Verify error state is active
    const errorState = page.getByTestId('error-state');
    await expect(errorState).toBeVisible();

    // Verify data container is not visible
    const dataContainer = page.getByTestId('data-container');
    await expect(dataContainer).not.toBeVisible();

    // Verify data list is not visible
    const dataList = page.getByTestId('data-list');
    await expect(dataList).not.toBeVisible();

    // Verify error message contains correct text
    await expect(errorMessage).toContainText('Failed to load data');
  });
});
